#![cfg_attr(not(feature = "std"), no_std)]

pub use uuid_impl::{fmt, Builder, Error};

#[derive(Clone, Copy, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd)]
#[repr(transparent)]
pub struct Uuid(uuid_impl::Uuid);

impl Uuid {
    #[cfg(feature = "v4")]
    #[inline]
    pub fn new_v4() -> Self {
        Self(uuid_impl::Uuid::new_v4())
    }

    #[inline]
    pub const fn hyphenated(self) -> fmt::Hyphenated {
        self.0.hyphenated()
    }

    #[inline]
    pub fn as_hyphenated(&self) -> &fmt::Hyphenated {
        self.0.as_hyphenated()
    }

    #[inline]
    pub const fn simple(self) -> fmt::Simple {
        self.0.simple()
    }

    #[inline]
    pub fn as_simple(&self) -> &fmt::Simple {
        self.0.as_simple()
    }

    #[inline]
    pub fn to_hyphenated_ref(&self) -> &fmt::Hyphenated {
        self.as_hyphenated()
    }

    #[inline]
    pub fn to_simple_ref(&self) -> &fmt::Simple {
        self.as_simple()
    }
}

impl core::fmt::Display for Uuid {
    #[inline]
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        core::fmt::Display::fmt(&self.0, f)
    }
}

impl core::ops::Deref for Uuid {
    type Target = uuid_impl::Uuid;

    #[inline]
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl From<uuid_impl::Uuid> for Uuid {
    #[inline]
    fn from(uuid: uuid_impl::Uuid) -> Self {
        Self(uuid)
    }
}

impl From<Uuid> for uuid_impl::Uuid {
    #[inline]
    fn from(uuid: Uuid) -> Self {
        uuid.0
    }
}

